  `lokasi_id` bigint unsigned NOT NULL,
  `periode_mulai_layanan` date NOT NULL,
  `periode_akhir_layanan` date NOT NULL,
  `jumlah_hari` int unsigned NOT NULL,
  `harga_bulanan_snapshot` decimal(18,2) NOT NULL,
