  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_billing_details_billing_id` (`billing_id`),
  KEY `idx_billing_details_lokasi_id` (`lokasi_id`),
