--
-- Table structure for table `lokasi`
--

DROP TABLE IF EXISTS `lokasi`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lokasi` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `kode_kontrak` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `pelanggan_id` bigint unsigned NOT NULL,
  `previous_lokasi_id` bigint unsigned DEFAULT NULL,
  `kategori` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nama_lokasi` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `core` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sharing_core` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `periode_awal` date NOT NULL,
  `periode_berakhir` date NOT NULL,
  `durasi_kontrak_bulan` int unsigned DEFAULT NULL,
  `no_kontrak` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nilai_kontrak` decimal(18,2) DEFAULT NULL,
  `biaya_aktivasi` decimal(18,2) NOT NULL DEFAULT '0.00',
  `perbulan` decimal(18,2) NOT NULL DEFAULT '0.00',
  `nilai_periode_aktif` decimal(18,2) NOT NULL DEFAULT '0.00',
  `status_kontrak` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `jenis_perubahan_kontrak` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `alasan_perubahan` text COLLATE utf8mb4_unicode_ci,
  `link_folder_berkas` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `keterangan` text COLLATE utf8mb4_unicode_ci,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_lokasi_kode_kontrak` (`kode_kontrak`),
  KEY `idx_lokasi_pelanggan_id` (`pelanggan_id`),
  KEY `idx_lokasi_previous_lokasi_id` (`previous_lokasi_id`),
  KEY `idx_lokasi_nama_lokasi` (`nama_lokasi`),
  KEY `idx_lokasi_status_kontrak` (`status_kontrak`),
  KEY `idx_lokasi_periode_berakhir` (`periode_berakhir`),
  CONSTRAINT `fk_lokasi_pelanggan` FOREIGN KEY (`pelanggan_id`) REFERENCES `pelanggan` (`id`),
  CONSTRAINT `fk_lokasi_previous` FOREIGN KEY (`previous_lokasi_id`) REFERENCES `lokasi` (`id`),
  CONSTRAINT `chk_lokasi_core_format` CHECK (((`core` is null) or (`core` = _utf8mb4'') or (`core` like _utf8mb4'% Core'))),
  CONSTRAINT `chk_lokasi_core_xor_sharing` CHECK (((`core` is null) or (trim(`core`) = _utf8mb4'') or (`sharing_core` is null) or (trim(`sharing_core`) = _utf8mb4''))),
  CONSTRAINT `chk_lokasi_periode` CHECK ((`periode_berakhir` >= `periode_awal`)),
  CONSTRAINT `chk_lokasi_sharing_core` CHECK (((`sharing_core` is null) or (`sharing_core` in (_utf8mb4'1/2',_utf8mb4'1/4',_utf8mb4'1/8',_utf8mb4'1/16',_utf8mb4'1/32')))),
  CONSTRAINT `chk_lokasi_status` CHECK ((`status_kontrak` in (_utf8mb4'Beroperasi',_utf8mb4'Belum Beroperasi',_utf8mb4'Proses Perpanjangan',_utf8mb4'Diperpanjang',_utf8mb4'Di-upgrade',_utf8mb4'Berhenti')))
) ENGINE=InnoDB AUTO_INCREMENT=331 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

